// Normalises the webhook payload and strips noise before it reaches the LLM.
// Accepts {from_name, from_email, subject, body, channel} (aliases: name, email, message, text).
const MAX_CHARS = 6000;
const out = [];
for (const item of $input.all()) {
  const p = item.json.body ?? item.json;
  const email = String(p.from_email ?? p.email ?? '').trim().toLowerCase();
  const raw = String(p.body ?? p.message ?? p.text ?? '');
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error(`Invalid or missing from_email: "${email}"`);
  if (!raw.trim()) throw new Error('Message body is empty');

  const body = raw
    .split(/\n-- ?\n|\nOn .+wrote:\n|\nLe .+a écrit :\n|\n-----Original Message-----/)[0] // drop quoted thread & signature
    .split('\n').filter((line) => !line.trim().startsWith('>')).join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim()
    .slice(0, MAX_CHARS);

  out.push({
    json: {
      message_id: p.message_id ?? `msg_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 7)}`,
      received_at: new Date().toISOString(),
      channel: p.channel ?? 'email',
      from_name: String(p.from_name ?? p.name ?? '').trim() || email.split('@')[0],
      from_email: email,
      subject: String(p.subject ?? '(no subject)').trim().slice(0, 200),
      body,
    },
  });
}
return out;

