// Validates the model's JSON so a malformed answer can never break routing.
const cfg = $('Config').first().json;
const messages = $('Clean & validate input').all();
const ENUM = {
  category: ['sales_lead', 'support', 'billing', 'partnership', 'spam', 'other'],
  urgency: ['low', 'medium', 'high'],
  sentiment: ['positive', 'neutral', 'negative'],
};
const pick = (value, allowed, fallback) => {
  const v = String(value ?? '').toLowerCase().trim();
  return allowed.includes(v) ? v : fallback;
};
const text = (v, max = 200) => (v === null || v === undefined || v === '' ? null : String(v).slice(0, max));

return $input.all().map((item, i) => {
  const msg = messages[i].json;
  let ai = {};
  let ai_error = null;
  try {
    const raw = item.json.choices?.[0]?.message?.content ?? '';
    ai = JSON.parse(raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, ''));
  } catch (e) {
    ai_error = `Could not parse model output: ${e.message}`;
  }

  const category = pick(ai.category, ENUM.category, 'other');
  const urgency = pick(ai.urgency, ENUM.urgency, 'medium');
  const lead_score = category === 'sales_lead'
    ? Math.max(0, Math.min(100, Math.round(Number(ai.lead_score) || 0)))
    : 0;
  const budget = Number(ai.budget_eur);

  let route = 'human_review';
  if (category === 'spam') route = 'ignored';
  else if (category === 'sales_lead') route = lead_score >= cfg.hot_lead_threshold ? 'hot_lead' : 'nurture';
  else if (category === 'support' || category === 'billing') route = urgency === 'high' ? 'urgent_ticket' : 'ticket';

  return {
    json: {
      ...msg,
      category,
      urgency,
      sentiment: pick(ai.sentiment, ENUM.sentiment, 'neutral'),
      language: text(ai.language, 5) ?? 'en',
      summary: text(ai.summary, 300) ?? msg.subject,
      company: text(ai.company, 120),
      contact_name: text(ai.contact_name, 120) ?? msg.from_name,
      budget_eur: Number.isFinite(budget) && budget > 0 ? budget : null,
      timeline: text(ai.timeline, 120),
      product_interest: text(ai.product_interest, 120),
      lead_score,
      needs_human: Boolean(ai.needs_human) || ai_error !== null || route === 'human_review',
      route,
      ai_error,
      model: item.json.model ?? cfg.llm_model,
    },
    pairedItem: { item: i },
  };
});

