// Builds a Slack Block Kit message for the sales team (runs once per lead).
const lead = $('Hot lead?').item.json;
const draft = $json.choices?.[0]?.message?.content?.trim() || '(no draft generated)';
const money = lead.budget_eur ? `€${Number(lead.budget_eur).toLocaleString('en-US')}` : 'not stated';
return {
  json: {
    channel: 'sales-hot-leads',
    text: `Hot lead (${lead.lead_score}/100): ${lead.contact_name}${lead.company ? ' at ' + lead.company : ''}`,
    blocks: [
      { type: 'section', text: { type: 'mrkdwn', text: `*${lead.subject}*\n${lead.summary}` } },
      {
        type: 'section',
        fields: [
          { type: 'mrkdwn', text: `*Budget*\n${money}` },
          { type: 'mrkdwn', text: `*Timeline*\n${lead.timeline ?? 'not stated'}` },
          { type: 'mrkdwn', text: `*Interested in*\n${lead.product_interest ?? 'not stated'}` },
          { type: 'mrkdwn', text: `*Contact*\n${lead.from_email}` },
        ],
      },
      { type: 'section', text: { type: 'mrkdwn', text: `*Suggested first reply*\n${draft}` } },
      { type: 'context', elements: [{ type: 'mrkdwn', text: `Message ${lead.message_id} | scored by ${lead.model}` }] },
    ],
  },
};

